class Rectangle:
    def __init__(self, l, b):
        self.l = l
        self.b = b

    def area(self):
        return self.l * self.b

l, b = map(int, input().split())
r = Rectangle(l, b)
print(r.area())

import math
class Circle:
    def __init__(self, r):
        self.r = r

    def area(self):
        return round(math.pi * self.r * self.r, 2)

r = int(input())
c = Circle(r)
print(c.area())

class Employee:
    def __init__(self, salary):
        self.salary = salary

    def bonus(self):
        return self.salary * 0.1

s = int(input())
e = Employee(s)
print(int(e.bonus()))

class Student:
    def __init__(self, marks):
        self.marks = marks

    def grade(self):
        if self.marks >= 80:
            return 'A'
        elif self.marks >= 60:
            return 'C'
        else:
            return 'F'

m = int(input())
s = Student(m)
print(s.grade())

