class Parent:
    def show(self):
        return 'Parent Function'

class Child(Parent):
    def show(self):
        return 'Child Function'

obj = Child()
print(obj.show())

from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self):
        pass

class Rectangle(Shape):
    def __init__(self, l, b):
        self.l = l
        self.b = b

    def area(self):
        return self.l * self.b

l, b = map(int, input().split())
r = Rectangle(l, b)
print(r.area())

class Person:
    def __init__(self, name):
        self.name = name

class Employee(Person):
    def __init__(self, name, age):
        super().__init__(name)
        self.age = age

name, age = input().split()
e = Employee(name, age)
print(e.name, e.age)

